package com.jadhavr.erp.email.service;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;class TemplateDataCipherTest{@Test void encryptsAndAuthenticatesTemplateData(){TemplateDataCipher cipher=new TemplateDataCipher("a-long-test-secret-used-only-for-unit-tests");String encrypted=cipher.encrypt("reset-token-value");assertNotEquals("reset-token-value",encrypted);assertFalse(encrypted.contains("reset-token"));assertEquals("reset-token-value",cipher.decrypt(encrypted));}}
